CREATE TABLE IF NOT EXISTS sbc_research_sources (id BIGINT AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,source_type VARCHAR(40) NOT NULL,source_name VARCHAR(180) NOT NULL,url TEXT NOT NULL,query_text TEXT,content_hash CHAR(64) NOT NULL,content_excerpt LONGTEXT,confidence_score DECIMAL(6,4) NOT NULL DEFAULT 0.5,verified TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_research_source_hash(tenant_id,content_hash),INDEX idx_research_tenant_time(tenant_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sbc_research_claims (id BIGINT AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,topic VARCHAR(255) NOT NULL,claim_text TEXT NOT NULL,evidence_ids_json LONGTEXT NOT NULL,confidence_score DECIMAL(6,4) NOT NULL DEFAULT 0.5,status VARCHAR(30) NOT NULL DEFAULT 'CANDIDATE',source_count INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_research_claim_topic(tenant_id,topic),INDEX idx_research_claim_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sbc_research_learning (id BIGINT AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,learning_type VARCHAR(80) NOT NULL,subject_key VARCHAR(255) NOT NULL,observation_json LONGTEXT NOT NULL,outcome VARCHAR(80) NOT NULL,confidence_delta DECIMAL(8,5) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,INDEX idx_research_learning_subject(tenant_id,subject_key,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
